/**
 * In-memory Event Bus for inter-service communication.
 * Services publish events and other services subscribe to them.
 */

type EventCallback = (payload: any) => void;

class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Publish an event with a payload.
   * All subscribers to this event type will be called.
   */
  publish(event: string, payload: any): void {
    const callbacks = this.subscribers.get(event) || [];
    callbacks.forEach(callback => {
      try {
        callback(payload);
      } catch (error) {
        console.error(`Error in event subscriber for ${event}:`, error);
      }
    });
  }

  /**
   * Subscribe to an event.
   * Returns an unsubscribe function.
   */
  subscribe(event: string, callback: EventCallback): () => void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);

    // Return unsubscribe function
    return () => {
      const callbacks = this.subscribers.get(event);
      if (callbacks) {
        const index = callbacks.indexOf(callback);
        if (index > -1) {
          callbacks.splice(index, 1);
        }
      }
    };
  }

  /**
   * Clear all subscribers for testing purposes.
   */
  clear(): void {
    this.subscribers.clear();
  }
}

export const eventBus = new EventBus();

/**
 * User Service
 * Manages user data and operations.
 * Each service owns its own data store.
 */

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface CreateUserInput {
  name: string;
  email: string;
}

export interface UpdateUserInput {
  name?: string;
  email?: string;
}

class UserService {
  private store: Map<string, User> = new Map();

  /**
   * Get all users.
   */
  getAllUsers(): User[] {
    return Array.from(this.store.values());
  }

  /**
   * Get a user by ID.
   */
  getUserById(id: string): User | undefined {
    return this.store.get(id);
  }

  /**
   * Create a new user.
   */
  createUser(input: CreateUserInput): User {
    const user: User = {
      id: randomUUID(),
      name: input.name,
      email: input.email,
    };
    this.store.set(user.id, user);
    return user;
  }

  /**
   * Update a user.
   * Returns the updated user or undefined if not found.
   */
  updateUser(id: string, input: UpdateUserInput): User | undefined {
    const user = this.store.get(id);
    if (!user) return undefined;

    if (input.name !== undefined) user.name = input.name;
    if (input.email !== undefined) user.email = input.email;

    this.store.set(id, user);
    return user;
  }

  /**
   * Delete a user.
   * Returns true if deleted, false if not found.
   */
  deleteUser(id: string): boolean {
    return this.store.delete(id);
  }
}

export const userService = new UserService();

/**
 * Project Service
 * Manages project data and operations.
 */

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface CreateProjectInput {
  name: string;
  description: string;
}

export interface UpdateProjectInput {
  name?: string;
  description?: string;
}

class ProjectService {
  private store: Map<string, Project> = new Map();

  /**
   * Get all projects.
   */
  getAllProjects(): Project[] {
    return Array.from(this.store.values());
  }

  /**
   * Get a project by ID.
   */
  getProjectById(id: string): Project | undefined {
    return this.store.get(id);
  }

  /**
   * Create a new project.
   */
  createProject(input: CreateProjectInput): Project {
    const project: Project = {
      id: randomUUID(),
      name: input.name,
      description: input.description,
      memberIds: [],
    };
    this.store.set(project.id, project);
    return project;
  }

  /**
   * Update a project.
   * Returns the updated project or undefined if not found.
   */
  updateProject(id: string, input: UpdateProjectInput): Project | undefined {
    const project = this.store.get(id);
    if (!project) return undefined;

    if (input.name !== undefined) project.name = input.name;
    if (input.description !== undefined) project.description = input.description;

    this.store.set(id, project);
    return project;
  }

  /**
   * Delete a project.
   * Returns true if deleted, false if not found.
   */
  deleteProject(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Add a member to a project.
   * Returns the updated project or undefined if not found.
   */
  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      this.store.set(projectId, project);
    }
    return project;
  }

  /**
   * Remove a member from a project.
   * Returns the updated project or undefined if not found.
   */
  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    project.memberIds = project.memberIds.filter(id => id !== userId);
    this.store.set(projectId, project);
    return project;
  }
}

export const projectService = new ProjectService();

/**
 * Task Service
 * Manages task data and operations.
 * Publishes events for task status changes and assignments.
 */

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface CreateTaskInput {
  title: string;
  description: string;
  projectId: string;
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
}

class TaskService {
  private store: Map<string, Task> = new Map();

  /**
   * Get all tasks for a project.
   */
  getTasksByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(t => t.projectId === projectId);
  }

  /**
   * Get a task by ID.
   */
  getTaskById(id: string): Task | undefined {
    return this.store.get(id);
  }

  /**
   * Create a new task.
   */
  createTask(input: CreateTaskInput): Task {
    const task: Task = {
      id: randomUUID(),
      title: input.title,
      description: input.description,
      status: 'todo',
      assigneeId: null,
      projectId: input.projectId,
    };
    this.store.set(task.id, task);
    return task;
  }

  /**
   * Update task title and description.
   * Returns the updated task or undefined if not found.
   */
  updateTask(id: string, input: UpdateTaskInput): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    if (input.title !== undefined) task.title = input.title;
    if (input.description !== undefined) task.description = input.description;

    this.store.set(id, task);
    return task;
  }

  /**
   * Delete a task.
   * Returns true if deleted, false if not found.
   */
  deleteTask(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Change task status with forward-only validation.
   * Valid transitions: todo -> in-progress -> done
   * Returns the updated task or undefined if not found.
   * Throws an error if the transition is invalid.
   */
  changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    const oldStatus = task.status;

    // Validate forward-only transitions
    if (oldStatus === newStatus) {
      return task; // No change needed
    }

    const isValidTransition =
      (oldStatus === 'todo' && newStatus === 'in-progress') ||
      (oldStatus === 'in-progress' && newStatus === 'done');

    if (!isValidTransition) {
      throw new Error(
        `Invalid status transition from "${oldStatus}" to "${newStatus}". Only forward transitions are allowed (todo -> in-progress -> done).`
      );
    }

    task.status = newStatus;
    this.store.set(id, task);

    // Publish event for status change
    eventBus.publish('task.statusChanged', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });

    return task;
  }

  /**
   * Assign a task to a user.
   * Returns the updated task or undefined if not found.
   */
  assignTask(id: string, assigneeId: string): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    const previousAssigneeId = task.assigneeId;
    task.assigneeId = assigneeId;
    this.store.set(id, task);

    // Only publish event if assignment changed
    if (previousAssigneeId !== assigneeId) {
      eventBus.publish('task.assigned', {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId,
      });
    }

    return task;
  }
}

export const taskService = new TaskService();

/**
 * Comment Service
 * Manages comment data and operations.
 * Publishes events when comments are added.
 */

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';
import { userService } from './user-service';
import { taskService } from './task-service';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export interface CreateCommentInput {
  taskId: string;
  authorId: string;
  body: string;
}

class CommentService {
  private store: Map<string, Comment> = new Map();

  /**
   * Get all comments for a task.
   */
  getCommentsByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(c => c.taskId === taskId);
  }

  /**
   * Get a comment by ID.
   */
  getCommentById(id: string): Comment | undefined {
    return this.store.get(id);
  }

  /**
   * Create a new comment.
   * Publishes a comment.added event.
   */
  createComment(input: CreateCommentInput): Comment {
    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    // Publish event for comment added
    // Get task and author info for the event
    const task = taskService.getTaskById(input.taskId);
    const author = userService.getUserById(input.authorId);

    eventBus.publish('comment.added', {
      commentId: comment.id,
      taskId: input.taskId,
      taskTitle: task?.title || 'Unknown Task',
      authorId: input.authorId,
      authorName: author?.name || 'Unknown Author',
    });

    return comment;
  }

  /**
   * Delete a comment.
   * Returns true if deleted, false if not found.
   */
  deleteComment(id: string): boolean {
    return this.store.delete(id);
  }
}

export const commentService = new CommentService();

/**
 * Notification Service
 * Manages notification data and operations.
 * Subscribes to events from Task and Comment services.
 */

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
}

class NotificationService {
  private store: Map<string, Notification> = new Map();

  constructor() {
    // Subscribe to task.assigned event
    eventBus.subscribe('task.assigned', (payload: any) => {
      this.handleTaskAssigned(payload);
    });

    // Subscribe to task.statusChanged event
    eventBus.subscribe('task.statusChanged', (payload: any) => {
      this.handleTaskStatusChanged(payload);
    });

    // Subscribe to comment.added event
    eventBus.subscribe('comment.added', (payload: any) => {
      this.handleCommentAdded(payload);
    });
  }

  /**
   * Handle task.assigned event
   */
  private handleTaskAssigned(payload: any): void {
    const { taskId, taskTitle, assigneeId } = payload;
    if (assigneeId) {
      const message = `You have been assigned to task: "${taskTitle}"`;
      this.createNotificationForUser(assigneeId, message);
    }
  }

  /**
   * Handle task.statusChanged event
   */
  private handleTaskStatusChanged(payload: any): void {
    const { taskId, taskTitle, assigneeId, oldStatus, newStatus } = payload;
    if (assigneeId) {
      const message = `Task "${taskTitle}" status changed from ${oldStatus} to ${newStatus}`;
      this.createNotificationForUser(assigneeId, message);
    }
  }

  /**
   * Handle comment.added event
   */
  private handleCommentAdded(payload: any): void {
    const { commentId, taskId, taskTitle, authorId, authorName } = payload;
    // In a real system, we might notify all task watchers or assignees
    // For this demo, we'll just log it
    console.log(
      `[Notification Service] Comment added on task "${taskTitle}" by ${authorName}`
    );
  }

  /**
   * Create a notification for a user.
   */
  private createNotificationForUser(userId: string, message: string): void {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
  }

  /**
   * Get all notifications for a user.
   */
  getNotificationsByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter(n => n.userId === userId);
  }

  /**
   * Get a notification by ID.
   */
  getNotificationById(id: string): Notification | undefined {
    return this.store.get(id);
  }

  /**
   * Mark a notification as read.
   * Returns the updated notification or undefined if not found.
   */
  markAsRead(id: string): Notification | undefined {
    const notification = this.store.get(id);
    if (!notification) return undefined;

    notification.read = true;
    this.store.set(id, notification);
    return notification;
  }
}

export const notificationService = new NotificationService();

/**
 * API Router
 * Single entry point for all HTTP handling.
 * Routes requests to appropriate service methods.
 */

import { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { userService } from './services/user-service';
import { projectService } from './services/project-service';
import { taskService } from './services/task-service';
import { commentService } from './services/comment-service';
import { notificationService } from './services/notification-service';

type Handler = (
  req: IncomingMessage,
  res: ServerResponse,
  params: Record<string, string>,
  body: any
) => Promise<void>;

interface Route {
  method: string;
  pattern: RegExp;
  handler: Handler;
}

class Router {
  private routes: Route[] = [];

  constructor() {
    this.setupRoutes();
  }

  private setupRoutes(): void {
    // ============ USER ROUTES ============

    // GET /users
    this.addRoute('GET', /^\/users$/, async (req, res) => {
      const users = userService.getAllUsers();
      this.sendJSON(res, 200, users);
    });

    // POST /users
    this.addRoute('POST', /^\/users$/, async (req, res, params, body) => {
      const user = userService.createUser(body);
      this.sendJSON(res, 201, user);
    });

    // GET /users/:id
    this.addRoute('GET', /^\/users\/([^/]+)$/, async (req, res, params) => {
      const user = userService.getUserById(params.id);
      if (!user) {
        this.sendJSON(res, 404, { error: 'User not found' });
        return;
      }
      this.sendJSON(res, 200, user);
    });

    // PUT /users/:id
    this.addRoute('PUT', /^\/users\/([^/]+)$/, async (req, res, params, body) => {
      const user = userService.updateUser(params.id, body);
      if (!user) {
        this.sendJSON(res, 404, { error: 'User not found' });
        return;
      }
      this.sendJSON(res, 200, user);
    });

    // DELETE /users/:id
    this.addRoute('DELETE', /^\/users\/([^/]+)$/, async (req, res, params) => {
      const deleted = userService.deleteUser(params.id);
      if (!deleted) {
        this.sendJSON(res, 404, { error: 'User not found' });
        return;
      }
      res.writeHead(204);
      res.end();
    });

    // ============ PROJECT ROUTES ============

    // GET /projects
    this.addRoute('GET', /^\/projects$/, async (req, res) => {
      const projects = projectService.getAllProjects();
      this.sendJSON(res, 200, projects);
    });

    // POST /projects
    this.addRoute('POST', /^\/projects$/, async (req, res, params, body) => {
      const project = projectService.createProject(body);
      this.sendJSON(res, 201, project);
    });

    // GET /projects/:id
    this.addRoute(
      'GET',
      /^\/projects\/([^/]+)$/,
      async (req, res, params) => {
        const project = projectService.getProjectById(params.id);
        if (!project) {
          this.sendJSON(res, 404, { error: 'Project not found' });
          return;
        }
        this.sendJSON(res, 200, project);
      }
    );

    // PUT /projects/:id
    this.addRoute(
      'PUT',
      /^\/projects\/([^/]+)$/,
      async (req, res, params, body) => {
        const project = projectService.updateProject(params.id, body);
        if (!project) {
          this.sendJSON(res, 404, { error: 'Project not found' });
          return;
        }
        this.sendJSON(res, 200, project);
      }
    );

    // DELETE /projects/:id
    this.addRoute(
      'DELETE',
      /^\/projects\/([^/]+)$/,
      async (req, res, params) => {
        const deleted = projectService.deleteProject(params.id);
        if (!deleted) {
          this.sendJSON(res, 404, { error: 'Project not found' });
          return;
        }
        res.writeHead(204);
        res.end();
      }
    );

    // POST /projects/:id/members
    this.addRoute(
      'POST',
      /^\/projects\/([^/]+)\/members$/,
      async (req, res, params, body) => {
        const project = projectService.addMember(params.id, body.userId);
        if (!project) {
          this.sendJSON(res, 404, { error: 'Project not found' });
          return;
        }
        this.sendJSON(res, 200, project);
      }
    );

    // DELETE /projects/:id/members
    this.addRoute(
      'DELETE',
      /^\/projects\/([^/]+)\/members$/,
      async (req, res, params, body) => {
        const project = projectService.removeMember(params.id, body.userId);
        if (!project) {
          this.sendJSON(res, 404, { error: 'Project not found' });
          return;
        }
        this.sendJSON(res, 200, project);
      }
    );

    // ============ TASK ROUTES ============

    // GET /tasks (by projectId query param)
    this.addRoute('GET', /^\/tasks$/, async (req, res) => {
      const url = new URL(req.url || '', `http://${req.headers.host}`);
      const projectId = url.searchParams.get('projectId');
      if (!projectId) {
        this.sendJSON(res, 400, { error: 'projectId query parameter required' });
        return;
      }
      const tasks = taskService.getTasksByProject(projectId);
      this.sendJSON(res, 200, tasks);
    });

    // POST /tasks
    this.addRoute('POST', /^\/tasks$/, async (req, res, params, body) => {
      const task = taskService.createTask(body);
      this.sendJSON(res, 201, task);
    });

    // GET /tasks/:id
    this.addRoute('GET', /^\/tasks\/([^/]+)$/, async (req, res, params) => {
      const task = taskService.getTaskById(params.id);
      if (!task) {
        this.sendJSON(res, 404, { error: 'Task not found' });
        return;
      }
      this.sendJSON(res, 200, task);
    });

    // PUT /tasks/:id
    this.addRoute('PUT', /^\/tasks\/([^/]+)$/, async (req, res, params, body) => {
      const task = taskService.updateTask(params.id, body);
      if (!task) {
        this.sendJSON(res, 404, { error: 'Task not found' });
        return;
      }
      this.sendJSON(res, 200, task);
    });

    // DELETE /tasks/:id
    this.addRoute('DELETE', /^\/tasks\/([^/]+)$/, async (req, res, params) => {
      const deleted = taskService.deleteTask(params.id);
      if (!deleted) {
        this.sendJSON(res, 404, { error: 'Task not found' });
        return;
      }
      res.writeHead(204);
      res.end();
    });

    // PUT /tasks/:id/status
    this.addRoute(
      'PUT',
      /^\/tasks\/([^/]+)\/status$/,
      async (req, res, params, body) => {
        try {
          const task = taskService.changeStatus(params.id, body.status);
          if (!task) {
            this.sendJSON(res, 404, { error: 'Task not found' });
            return;
          }
          this.sendJSON(res, 200, task);
        } catch (error: any) {
          this.sendJSON(res, 400, { error: error.message });
        }
      }
    );

    // PUT /tasks/:id/assign
    this.addRoute(
      'PUT',
      /^\/tasks\/([^/]+)\/assign$/,
      async (req, res, params, body) => {
        const task = taskService.assignTask(params.id, body.assigneeId);
        if (!task) {
          this.sendJSON(res, 404, { error: 'Task not found' });
          return;
        }
        this.sendJSON(res, 200, task);
      }
    );

    // ============ COMMENT ROUTES ============

    // GET /comments (by taskId query param)
    this.addRoute('GET', /^\/comments$/, async (req, res) => {
      const url = new URL(req.url || '', `http://${req.headers.host}`);
      const taskId = url.searchParams.get('taskId');
      if (!taskId) {
        this.sendJSON(res, 400, { error: 'taskId query parameter required' });
        return;
      }
      const comments = commentService.getCommentsByTask(taskId);
      this.sendJSON(res, 200, comments);
    });

    // POST /comments
    this.addRoute('POST', /^\/comments$/, async (req, res, params, body) => {
      const comment = commentService.createComment(body);
      this.sendJSON(res, 201, comment);
    });

    // GET /comments/:id
    this.addRoute('GET', /^\/comments\/([^/]+)$/, async (req, res, params) => {
      const comment = commentService.getCommentById(params.id);
      if (!comment) {
        this.sendJSON(res, 404, { error: 'Comment not found' });
        return;
      }
      this.sendJSON(res, 200, comment);
    });

    // DELETE /comments/:id
    this.addRoute('DELETE', /^\/comments\/([^/]+)$/, async (req, res, params) => {
      const deleted = commentService.deleteComment(params.id);
      if (!deleted) {
        this.sendJSON(res, 404, { error: 'Comment not found' });
        return;
      }
      res.writeHead(204);
      res.end();
    });

    // ============ NOTIFICATION ROUTES ============

    // GET /notifications (by userId query param)
    this.addRoute('GET', /^\/notifications$/, async (req, res) => {
      const url = new URL(req.url || '', `http://${req.headers.host}`);
      const userId = url.searchParams.get('userId');
      if (!userId) {
        this.sendJSON(res, 400, { error: 'userId query parameter required' });
        return;
      }
      const notifications = notificationService.getNotificationsByUser(userId);
      this.sendJSON(res, 200, notifications);
    });

    // PUT /notifications/:id/read
    this.addRoute(
      'PUT',
      /^\/notifications\/([^/]+)\/read$/,
      async (req, res, params) => {
        const notification = notificationService.markAsRead(params.id);
        if (!notification) {
          this.sendJSON(res, 404, { error: 'Notification not found' });
          return;
        }
        this.sendJSON(res, 200, notification);
      }
    );
  }

  private addRoute(
    method: string,
    pattern: RegExp,
    handler: Handler
  ): void {
    this.routes.push({ method, pattern, handler });
  }

  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const pathname = new URL(req.url || '', `http://${req.headers.host}`).pathname;
    const method = req.method || 'GET';

    // Find matching route
    for (const route of this.routes) {
      if (route.method !== method) continue;

      const match = pathname.match(route.pattern);
      if (!match) continue;

      // Extract path parameters
      const params: Record<string, string> = {};
      if (match.length > 1) {
        params.id = match[1];
      }

      // Parse request body
      let body: any = {};
      if (method === 'POST' || method === 'PUT') {
        body = await this.parseBody(req);
      }

      try {
